"""Baseline buyer: data-backed anchoring, a concession schedule, multiple term sheets, cost-based closing.

No language model: every number comes from the published cost function C and the data package. It is
a reference to beat and a harness test, not a winner.

Per supplier it prepares:
  - a target price: the lower of the opening and current price, minus an anchor that follows the
    category goal; never below the should-cost (plus the sustainable margin in strategic/bottleneck
    cases, where squeezing the supplier costs C);
  - checkable arguments (data.Evidence): short notice against the contract, index moves below the
    asked increase, a weak scorecard, should-cost, the alternative quote, a cheaper rival in an RFQ.
Each round it offers up to three term sheets:
  A  the target-path price with every other negotiable term set to what minimises C;
  B  the same price on the supplier's own standing terms (a pure price move);
  C  a "cash" variant: shorter payment at the price that costs us the same C as A.
It holds a thread when the supplier agrees, makes a final offer, stops moving, comes close enough
or runs out of rounds; then it accepts the cheapest standing sheet that beats the alternative.
"""

import math
import threading
from dataclasses import dataclass, field

from arena_kit.cost import RELATIONSHIP_GOALS, complete_offer

from negotiator.data import Evidence, WorldData
from negotiator.session import Negotiation
from negotiator.strategy.base import Decision
from negotiator.telemetry import log

# Opening anchor below the lower of opening and current price, by category goal. Practice showed the
# bots' floors sit far below their openings (C_best often 15-25 % under C_open in leverage cases).
GOAL_ANCHOR = {
    "leverage": 0.18,
    "routine": 0.12,
    "stabilise": 0.08,
    "secure_supply": 0.05,
    "quality_first": 0.06,
}
# Share of the gap between our target and the supplier's price we may have given by each round - a
# ceiling; reciprocity (below) usually keeps us under it.
CONCESSION = [0.0, 0.15, 0.28, 0.40, 0.52, 0.63, 0.73, 0.82]
RECIPROCITY = 1.0  # our step, in % of our price, at most this times the supplier's last step in %
MIN_STEP = 0.004  # ... but at least 0.4 %, so a stalled supplier still sees movement
SANE_PRICE = 0.6  # never put a price below 60 % of the supplier's in front of it, even if C would allow
CLOSE_ENOUGH = 0.005  # within 0.5 % of the supplier's price: take it
MAX_CLAIMS = 3  # the arena checks at most 3 arguments per message
SIGNATURE = "Kind regards\nHollerau Pumpenwerke GmbH, Purchasing"


@dataclass
class SupplierPlan:
    supplier_id: str
    name: str
    open_price: float | None
    target_price: float | None
    floor_price: float | None
    evidence: list[Evidence] = field(default_factory=list)
    asked_cost_breakdown: bool = False
    offered: dict[str, float] = field(default_factory=dict)  # non-price terms -> highest price we offered


class BaselineStrategy:
    name = "baseline"

    def __init__(self, data: WorldData | None = None, llm=None) -> None:
        self.data = data
        self.plans: dict[str, SupplierPlan] = {}
        # Each ID counts once per case (a duplicate earns nothing); only a rival's offer may be cited
        # to every other bidder, once per supplier.
        self.used_refs: set[str] = set()
        self.used_rival_refs: set[tuple[str, str]] = set()
        self._claims_lock = threading.Lock()

    # ------------------------------------------------------------------ prepare
    def prepare(self, neg: Negotiation) -> None:
        case, buyer = neg.case, neg.buyer
        goal = buyer.get("category_goal", "leverage")
        parts = case.get("parts", [])
        current = buyer.get("current_unit_price")
        for sid, thread in neg.threads.items():
            _, terms = thread.standing
            open_price = terms.get("unit_price")
            full_cost = self._full_cost(parts, sid)
            std = thread.standard_terms
            if goal in RELATIONSHIP_GOALS and full_cost and {"payment_days", "incoterm"} <= std.keys():
                neg.supplier_estimates[sid] = {
                    "full_cost": full_cost,
                    "interest_rate": buyer.get("interest_rate", 0.08),
                    "standard": std,
                }
            floor = None
            if full_cost:
                margin = (buyer.get("sustainable_margin_pct") or 0) if goal in RELATIONSHIP_GOALS else 1.0
                floor = round(full_cost / (1 - margin / 100), 2)
            target = None
            if open_price is not None:
                base = min(open_price, current) if current else open_price
                target = base * (1 - GOAL_ANCHOR.get(goal, 0.06))
                if floor:
                    target = max(target, floor)
                target = round(min(target, open_price), 2)
            plan = SupplierPlan(sid, self._name(sid), open_price, target, floor)
            plan.evidence = self._evidence(neg, sid, open_price, current)
            self.plans[sid] = plan
            neg.recorder.event(
                "plan",
                session_id=neg.session_id,
                case_id=neg.case_id,
                supplier_id=sid,
                open_price=open_price,
                target_price=target,
                floor_price=floor,
                full_cost=full_cost,
                evidence=[
                    {"kind": e.kind, "refs": e.refs, "strength": round(e.strength, 2), "sentence": e.sentence}
                    for e in plan.evidence
                ],
            )
            log.info(
                "%s plan: open %s target %s floor %s, %d argument(s)",
                sid,
                open_price,
                target,
                floor,
                len(plan.evidence),
            )

    def _full_cost(self, parts: list[str], supplier_id: str) -> float | None:
        if not self.data or not parts:
            return None
        rows = self.data.query(
            f"SELECT supplier_id, unit_cost FROM should_cost WHERE part_id IN ({','.join('?' for _ in parts)})",
            tuple(parts),
        )
        own = [r for r in rows if r["supplier_id"] == supplier_id]
        row = (own or rows or [None])[0]
        return row["unit_cost"] if row else None

    def _name(self, supplier_id: str) -> str:
        if self.data:
            name = self.data.supplier(supplier_id).get("name")
            if name:
                return name
        return supplier_id

    def _evidence(self, neg: Negotiation, sid: str, open_price: float | None, current: float | None) -> list[Evidence]:
        if not self.data:
            return []
        case, d = neg.case, self.data
        parts = case.get("parts", [])
        asked = (open_price / current - 1) * 100 if open_price and current else None
        trigger = case.get("trigger_doc")
        fact = d.fact(trigger) if trigger else None
        if fact and fact.get("asked_pct") is not None:
            asked = fact["asked_pct"]
        out: list[Evidence] = []
        if fact and fact.get("supplier") == sid:
            out += d.evidence_notice(trigger, sid)
        out += d.evidence_indices(parts, asked)
        out += d.evidence_scorecard(sid)
        if open_price:
            out += d.evidence_should_cost(parts, open_price)
        alt = neg.buyer.get("alternative") or {}
        if alt.get("kind") == "quote" and alt.get("ref"):
            alt_price = (alt.get("terms") or {}).get("unit_price")
            if alt_price and open_price and alt_price < open_price:
                out += d.evidence_quote(alt["ref"])
        return sorted(out, key=lambda e: -e.strength)

    # ------------------------------------------------------------------ per thread
    def decide(self, neg: Negotiation, supplier_id: str) -> Decision:
        t, plan = neg.threads[supplier_id], self.plans[supplier_id]
        if not t.live:
            return Decision.drop(supplier_id, f"thread {t.status}")
        sheet_id, theirs = t.standing
        if t.status in ("agreed", "final_offer"):
            return Decision.hold(supplier_id, t.status)
        if theirs.get("unit_price") is None or plan.target_price is None:
            return Decision.hold(supplier_id, "no price to negotiate on")
        rounds_left = neg.case.get("round_limit", 10) - t.rounds_used
        if rounds_left <= 1:
            return Decision.hold(supplier_id, "last round: keep it for the close")
        if neg.seconds_to_deadline() < 120:
            return Decision.hold(supplier_id, "the deadline is near")
        their_path, our_path = t.price_path(), t.our_price_path()
        if len(our_path) >= 2 and len(their_path) >= 3 and len(set(their_path[-3:])) == 1:
            return Decision.hold(supplier_id, "the supplier stopped moving", price=their_path[-1])

        price = self._next_price(plan, theirs["unit_price"], our_path, t.rounds_used, their_path)
        if self._close_enough(neg, supplier_id, theirs, price):
            return Decision.hold(supplier_id, "close enough", ours=price, theirs=theirs["unit_price"])
        sheets = self._term_sheets(neg, supplier_id, theirs, price)
        if not sheets:
            return Decision.hold(supplier_id, "no term sheet beats the standing offer")
        claims = self._pick_claims(neg, supplier_id, plan, first=t.rounds_used == 0)
        message = self._message(neg, plan, sheets, claims, first=t.rounds_used == 0)
        c_theirs = neg.cost(supplier_id, theirs)
        return Decision(
            "message",
            supplier_id,
            message=message,
            rationale={
                "round": t.rounds_used + 1,
                "target": plan.target_price,
                "price": price,
                "their_price": theirs["unit_price"],
                "c_theirs": c_theirs,
                "c_sheets": [neg.cost(supplier_id, s["terms"]) for s in sheets],
                "claims": [c.kind for c in claims],
            },
        )

    def _next_price(
        self,
        plan: SupplierPlan,
        theirs: float,
        ours: list[float],
        round_index: int,
        their_path: list[float] | None = None,
    ) -> float:
        """Price of our C-optimal sheet this round: the concession schedule as a ceiling, and never a bigger
        step (in %) than the supplier's own last step - it moves, we move; it stands, we barely move."""
        share = CONCESSION[min(round_index, len(CONCESSION) - 1)]
        price = plan.target_price + (theirs - plan.target_price) * share
        if ours:
            their_step = 0.0
            if their_path and len(their_path) >= 2 and their_path[-2]:
                their_step = (their_path[-2] - their_path[-1]) / their_path[-2]
            step_cap = ours[-1] * max(their_step * RECIPROCITY, MIN_STEP)
            price = min(price, ours[-1] + step_cap)
            price = max(price, ours[-1])  # never go back on an offer
        return round(min(price, theirs), 2)

    def _term_sheets(self, neg: Negotiation, sid: str, theirs: dict, price: float) -> list[dict]:
        """A menu of equal cost to us (MESO): A is the C-optimal structure at `price`; B is the supplier's own
        structure and C a shorter-payment variant, each priced so that its C equals A's. The supplier picks
        what suits it; whatever it picks costs us the same. Each structure's price only ever rises."""
        case, plan = neg.case, self.plans[sid]
        c_theirs = neg.cost(sid, theirs)
        ideal = complete_offer(case, self._optimise(neg, sid, {**theirs, "unit_price": price}))
        c_target = neg.cost(sid, ideal)
        candidates = [ideal]
        own = complete_offer(case, {**theirs, "unit_price": price})
        own["unit_price"] = self._iso_cost_price(neg, sid, own, c_target)
        candidates.append(own)
        if "payment_days" in case["negotiable"]:
            options = sorted(o for o in case.get("term_options", {}).get("payment_days", []) if o is not None)
            shorter = [o for o in options if o < ideal.get("payment_days", 0)]
            if shorter:
                cash = {**ideal, "payment_days": shorter[len(shorter) // 2]}
                cash["unit_price"] = self._iso_cost_price(neg, sid, cash, c_target)
                candidates.append(complete_offer(case, cash))
        out, seen = [], set()
        for terms in candidates:
            key = structure_key(terms)
            terms["unit_price"] = round(max(terms["unit_price"], plan.offered.get(key, 0.0)), 2)
            if key in seen or not neg.keeps_must_haves(sid, terms):
                continue
            if terms["unit_price"] < theirs["unit_price"] * SANE_PRICE:
                continue
            if neg.cost(sid, terms) >= c_theirs:  # never offer something dearer than what is on the table
                continue
            seen.add(key)
            out.append({"terms": terms})
        for sheet in out[:3]:
            key = structure_key(sheet["terms"])
            plan.offered[key] = max(plan.offered.get(key, 0.0), sheet["terms"]["unit_price"])
        return out[:3]

    def _close_enough(self, neg: Negotiation, sid: str, theirs: dict, price: float) -> bool:
        """Hold only when the standing offer costs us no more than our best structure at its price would:
        close in price on a worse structure (e.g. a shorter contract) is not close in C."""
        if price < theirs["unit_price"] * (1 - CLOSE_ENOUGH):
            return False
        best_at_theirs = complete_offer(neg.case, self._optimise(neg, sid, dict(theirs)))
        return neg.cost(sid, theirs) <= neg.cost(sid, best_at_theirs) * (1 + CLOSE_ENOUGH)

    def _optimise(self, neg: Negotiation, sid: str, terms: dict) -> dict:
        """Coordinate descent over the non-price options: each field set to what minimises C."""
        options = neg.case.get("term_options", {})
        best = dict(terms)
        for _ in range(2):
            for f in neg.case["negotiable"]:
                if f == "unit_price" or not options.get(f):
                    continue

                def key(value, f=f):
                    trial = {**best, f: value}
                    ok = neg.keeps_must_haves(sid, trial)
                    return (neg.cost(sid, trial) if ok else math.inf, repr(value))

                best[f] = min(options[f], key=key)
        return best

    def _iso_cost_price(self, neg: Negotiation, sid: str, terms: dict, target_c: float) -> float:
        """The price at which these terms cost us `target_c` (C rises with the price)."""
        lo, hi = 0.0, terms["unit_price"] * 1.5
        for _ in range(40):
            mid = (lo + hi) / 2
            if neg.cost(sid, {**terms, "unit_price": mid}) > target_c:
                hi = mid
            else:
                lo = mid
        return round(lo, 2)

    def _pick_claims(self, neg: Negotiation, sid: str, plan: SupplierPlan, first: bool) -> list[Evidence]:
        pool = list(plan.evidence)
        rival = self._rival_evidence(neg, sid)
        if rival:
            pool.insert(0, rival)
        return self._claim(sid, pool, MAX_CLAIMS if first else 1, distinct_kinds=first)

    def _claim(self, sid: str, pool: list[Evidence], limit: int, distinct_kinds: bool = False) -> list[Evidence]:
        """Take up to `limit` arguments from `pool` that have not been used yet (each ID counts once per
        case; a rival's offer once per supplier) and mark them used. Threads of one case call this at once."""
        with self._claims_lock:
            picked: list[Evidence] = []
            kinds = set()
            for e in pool:
                if len(picked) >= limit:
                    break
                if e.kind == "rival_offer":
                    if any((sid, r) in self.used_rival_refs for r in e.refs):
                        continue
                elif any(r in self.used_refs for r in e.refs) or (distinct_kinds and e.kind in kinds):
                    continue
                picked.append(e)
                kinds.add(e.kind)
            for e in picked:
                if e.kind == "rival_offer":
                    self.used_rival_refs.update((sid, r) for r in e.refs)
                else:
                    self.used_refs.update(e.refs)
            return picked

    def _rival_evidence(self, neg: Negotiation, sid: str) -> Evidence | None:
        """In an RFQ: a rival's standing offer that is cheaper than this supplier's."""
        if len(neg.threads) < 2:
            return None
        mine = neg.threads[sid].standing[1].get("unit_price")
        best = None
        for other, t in neg.threads.items():
            offer_id, terms = t.standing
            if other == sid or not offer_id or terms.get("unit_price") is None:
                continue
            if mine and terms["unit_price"] < mine and (best is None or terms["unit_price"] < best[1]):
                best = (offer_id, terms["unit_price"])
        if not best:
            return None
        return Evidence(
            kind="rival_offer",
            refs=[best[0]],
            sentence=f"Another bidder offers EUR {best[1]:.2f} per unit ({best[0]}).",
            strength=3.0,
        )

    def _message(
        self, neg: Negotiation, plan: SupplierPlan, sheets: list[dict], claims: list[Evidence], first: bool
    ) -> dict:
        case = neg.case
        lines = [f"Dear {plan.name} team," if plan.name != plan.supplier_id else "Dear Sir or Madam,", ""]
        if first:
            lines.append(
                "thank you for your quote. We have reviewed it against our data and cannot accept it as it stands."
            )
        else:
            lines.append("thank you for your reply. We have moved towards you; we need you to move as well.")
        lines += [c.sentence for c in claims]
        if first and not plan.asked_cost_breakdown:
            lines.append("Could you send us a cost breakdown for this part?")
            plan.asked_cost_breakdown = True
        lines.append("")
        lines.append("We can award on any of these options:" if len(sheets) > 1 else "Our proposal:")
        for i, sheet in enumerate(sheets):
            lines.append(f"Option {chr(65 + i)}: {describe(case, sheet['terms'])}")
        lines += ["", SIGNATURE]
        refs = sorted({r for c in claims for r in c.refs})
        return {
            "subject": f"{case.get('title', 'Your quote')}",
            "body": "\n".join(lines),
            "term_sheets": sheets,
            "refs": refs,
        }

    # ------------------------------------------------------------------ closing
    def conclude(self, neg: Negotiation) -> Decision:
        c_alt = neg.c_alt
        best = None
        for sid, t in neg.threads.items():
            sheet_id, terms = t.standing
            if not sheet_id or t.closed or t.status in ("walked_away", "no_bid"):
                continue
            if not neg.keeps_must_haves(sid, terms):
                continue
            c = neg.cost(sid, terms)
            if best is None or c < best[0]:
                best = (c, sid, sheet_id)
        if best and best[0] < c_alt:
            return Decision(
                "accept",
                best[1],
                term_sheet_id=best[2],
                rationale={
                    "c": best[0],
                    "c_alt": c_alt,
                    "why": "cheapest standing sheet beats the alternative",
                },
            )
        return Decision(
            "walk_away",
            next(iter(neg.threads)),
            rationale={
                "c_best_standing": best[0] if best else None,
                "c_alt": c_alt,
                "why": "nothing beats the alternative",
            },
        )

    def keepalive(self, neg: Negotiation, supplier_id: str) -> dict | None:
        t = neg.threads[supplier_id]
        if neg.case.get("round_limit", 10) - t.rounds_used <= 2:
            return None
        return {
            "subject": f"{neg.case.get('title', 'Your quote')}",
            "body": f"Dear {self.plans[supplier_id].name} team,\n\nthank you. While we complete our evaluation: "
            f"could you confirm your delivery capacity for our annual volume?\n\n{SIGNATURE}",
        }


def structure_key(terms: dict) -> str:
    """The non-price terms of a sheet: offers with the same structure must never get cheaper."""
    return repr(sorted((k, v) for k, v in terms.items() if k != "unit_price"))


def describe(case: dict, terms: dict) -> str:
    """A term sheet in words, for the e-mail body (the term sheet itself is what binds)."""
    unit = (case.get("buyer") or {}).get("price_unit")
    parts = []
    for k, v in terms.items():
        if k == "unit_price":
            parts.append(f"EUR {v:,.2f} per unit" + (f" ({unit})" if unit else ""))
        elif k == "payment_days":
            parts.append(f"payment {v} days net")
        elif k == "lead_time_days":
            parts.append(f"lead time {v} days")
        elif k == "contract_months":
            parts.append(f"{v}-month contract" if v else "single order")
        elif k == "volume_per_year":
            parts.append(f"{v:,} units a year")
        elif k == "effective_date":
            parts.append(f"price valid from {v}")
        elif k == "index_clause":
            parts.append(
                "no index clause"
                if not v
                else f"index clause on {v['series']} ({v['material_share']:.0%} material, deadband "
                f"{v['deadband_pct']}%, base {v['base_month']})"
            )
        elif k == "incoterm":
            parts.append(f"Incoterm {v}")
        elif k == "tooling_eur":
            parts.append(f"tooling EUR {v:,.2f}")
        elif k == "ppm_commitment":
            parts.append(f"quality commitment {v} ppm")
        elif k == "chargeback_eur_per_complaint":
            parts.append(f"chargeback EUR {v} per complaint")
        else:
            parts.append(f"{k} {v}")
    return ", ".join(parts)

"""One case being negotiated: the threads, the documents, every move and its telemetry.

`Negotiation` owns the session's state and talks to the arena; strategies only read it and decide.
Every move is recorded (events.jsonl, metrics) and the whole case is written to
`sessions/<session_id>.json` when it ends: case file, e-mails both ways, documents as text, each
decision with its rationale and the costs it saw, the result, the arena's trace and the back office.
"""

import math
import threading
import time
from dataclasses import dataclass, field

from arena_kit.cost import cost_breakdown, must_haves_ok, total_cost
from arena_kit.docs import quote_terms, read_document

from negotiator.client import ArenaClient, ArenaError
from negotiator.data import WorldData
from negotiator.guards import accept_problems, clean_message
from negotiator.telemetry import Recorder, log, safe_name, utc_now

ENDED_STATUSES = {"walked_away", "no_bid"}
MOVE_LIMIT_S = 60.0


class GuardRefused(Exception):
    """A move the hard rules (guards.py) refuse: it would break a must-have or lose to the alternative."""


@dataclass
class ThreadState:
    supplier_id: str
    messages: list[dict] = field(default_factory=list)  # both directions, in order; ours: from=buyer
    last_reply_at: float = field(default_factory=time.monotonic)
    timeouts: int = 0
    closed: str | None = None
    lock: threading.Lock = field(default_factory=threading.Lock, repr=False)

    @property
    def supplier_messages(self) -> list[dict]:
        return [m for m in self.messages if m.get("from") != "buyer"]

    @property
    def latest(self) -> dict:
        msgs = self.supplier_messages
        return msgs[-1] if msgs else {}

    @property
    def status(self) -> str:
        return "closed" if self.closed else self.latest.get("status", "open")

    @property
    def live(self) -> bool:
        return not self.closed and self.status not in ENDED_STATUSES

    @property
    def standing(self) -> tuple[str | None, dict]:
        sheets = self.latest.get("term_sheets") or []
        return (sheets[0]["term_sheet_id"], sheets[0]["terms"]) if sheets else (None, {})

    @property
    def rounds_used(self) -> int:
        return sum(1 for m in self.messages if m.get("from") == "buyer" and not m.get("action"))

    @property
    def standard_terms(self) -> dict:
        """The supplier's standard terms from its latest quote PDF: what closes for a missing field."""
        for msg in reversed(self.supplier_messages):
            for att in msg.get("attachments") or []:
                if att.get("name", "").startswith("quote") and att.get("text"):
                    return quote_terms(att["text"]).get("standard", {})
        return {}

    def price_path(self) -> list[float]:
        out = []
        for m in self.supplier_messages:
            sheets = m.get("term_sheets") or []
            if sheets and sheets[0]["terms"].get("unit_price") is not None:
                out.append(sheets[0]["terms"]["unit_price"])
        return out

    def our_price_path(self) -> list[float]:
        return [
            m["term_sheets"][0]["terms"]["unit_price"]
            for m in self.messages
            if m.get("from") == "buyer"
            and m.get("term_sheets")
            and m["term_sheets"][0]["terms"].get("unit_price") is not None
        ]

    def seconds_since_reply(self) -> float:
        return time.monotonic() - self.last_reply_at


class Negotiation:
    def __init__(
        self,
        client: ArenaClient,
        recorder: Recorder,
        data: WorldData | None = None,
        *,
        deadline: float | None = None,
        strategy_name: str = "",
    ) -> None:
        self.client, self.recorder, self.data = client, recorder, data
        self.deadline = deadline  # wall clock (time.time()) by which the case must close, e.g. a wave cap
        self.strategy_name = strategy_name
        self.case: dict = {}
        self.case_id = ""
        self.session_id = ""
        self.threads: dict[str, ThreadState] = {}
        self.decisions: list[dict] = []
        self.result: dict | None = None
        self.ended = threading.Event()
        self.started = time.time()
        self.supplier_estimates: dict[str, dict] = {}  # for the relationship term (stabilise, secure_supply)
        self._lock = threading.Lock()

    # ------------------------------------------------------------------ open / resume
    def open(self, case_id: str, case: dict | None = None) -> "Negotiation":
        self.case_id = case_id
        try:
            reply = self.client.open_session(case_id)
        except ArenaError as e:
            running = _running_session(e)
            if not running:
                raise
            return self.resume(running, case)
        self.session_id, self.case = reply["session_id"], reply["case"]
        if self.data:
            self.data.with_case(self.case)
        for sid, messages in reply["threads"].items():
            state = ThreadState(sid)
            for message in messages:
                state.messages.append(self._with_documents(message, sid))
            self.threads[sid] = state
        self._log_open(resumed=False)
        return self

    def resume(self, session_id: str, case: dict | None = None) -> "Negotiation":
        """Pick up a session this team already started (after a crash, or a final 409)."""
        self.session_id = session_id
        state = self.client.session(session_id)
        self.case_id = state.get("case_id", self.case_id)
        self.case = case or self.case
        for sid in state.get("threads", {}):
            thread = self.client.thread(session_id, sid)
            ts = ThreadState(sid, closed=thread.get("closed"))
            ts.messages = [
                self._with_documents(m, sid) if m.get("from") != "buyer" else m for m in thread.get("messages", [])
            ]
            self.threads[sid] = ts
        if state.get("status") == "ended":
            self.result = state.get("result") or {"deal": False, "end_reason": state.get("end_reason")}
            self.ended.set()
        self._log_open(resumed=True)
        return self

    def _log_open(self, resumed: bool) -> None:
        opening = {}
        for sid, t in self.threads.items():
            sheet_id, terms = t.standing
            opening[sid] = {
                "offer_id": sheet_id,
                "terms": terms,
                "c": self.cost(sid, terms),
                "standard_terms": t.standard_terms,
            }
        self.recorder.event(
            "session_opened",
            session_id=self.session_id,
            case_id=self.case_id,
            type=self.case.get("type"),
            goal=self.case.get("buyer", {}).get("category_goal"),
            suppliers=list(self.threads),
            resumed=resumed,
            opening=opening,
            c_alt=self.c_alt,
            strategy=self.strategy_name,
        )
        log.info(
            "%s %s: %s, %d supplier(s), C_alt=%s",
            "resumed" if resumed else "opened",
            self.case_id,
            self.case.get("title"),
            len(self.threads),
            _eur(self.c_alt),
        )

    # ------------------------------------------------------------------ documents
    def _with_documents(self, message: dict, supplier_id: str) -> dict:
        """Download every attachment of a supplier message, save the file, add its text."""
        for att in message.get("attachments") or []:
            if not att.get("attachment_id") or "text" in att:
                continue
            try:
                blob = self.client.attachment(self.session_id, att["attachment_id"])
            except ArenaError as e:
                log.warning("attachment %s: %s", att["attachment_id"], e)
                continue
            path = self.recorder.session_dir(self.session_id) / safe_name(f"{supplier_id}-{att['name']}")
            path.write_bytes(blob)
            try:
                att["text"] = read_document(att["name"], blob)
            except Exception as e:  # a document we cannot parse must not stop the case
                att["text"] = ""
                log.warning("cannot read %s: %s", att["name"], e)
            att["file"] = str(path.relative_to(self.recorder.dir))
            self.recorder.metrics.incr(f"documents.{att.get('type', 'unknown')}")
            self.recorder.event(
                "attachment",
                session_id=self.session_id,
                supplier_id=supplier_id,
                name=att["name"],
                type=att.get("type"),
                bytes=len(blob),
                file=att["file"],
            )
        return message

    # ------------------------------------------------------------------ costs
    @property
    def buyer(self) -> dict:
        return self.case.get("buyer", {})

    @property
    def c_alt(self) -> float:
        alt = self.buyer.get("alternative") or {}
        terms = alt.get("terms") or {}
        return total_cost(self.case, terms) if terms.get("unit_price") is not None else math.inf

    @property
    def c_open(self) -> float:
        """Our estimate of C_open: the cheapest opening quote that keeps the must-haves."""
        best = math.inf
        for sid, t in self.threads.items():
            first = next((m for m in t.supplier_messages if m.get("term_sheets")), None)
            if first and self.keeps_must_haves(sid, first["term_sheets"][0]["terms"]):
                best = min(best, self.cost(sid, first["term_sheets"][0]["terms"]))
        return best

    def cost(self, supplier_id: str, terms: dict) -> float:
        if not terms or terms.get("unit_price") is None:
            return math.inf
        t = self.threads.get(supplier_id)
        return total_cost(self.case, terms, t.standard_terms if t else None, self.supplier_estimates.get(supplier_id))

    def breakdown(self, supplier_id: str, terms: dict) -> dict:
        t = self.threads.get(supplier_id)
        return {
            k: round(v, 2)
            for k, v in cost_breakdown(
                self.case, terms, t.standard_terms if t else None, self.supplier_estimates.get(supplier_id)
            ).items()
        }

    def keeps_must_haves(self, supplier_id: str, terms: dict) -> bool:
        t = self.threads.get(supplier_id)
        return must_haves_ok(self.case, terms, t.standard_terms if t else None)

    def seconds_to_deadline(self) -> float:
        return math.inf if self.deadline is None else self.deadline - time.time()

    # ------------------------------------------------------------------ moves
    def send(self, supplier_id: str, message: dict, rationale: dict | None = None) -> dict | None:
        """Send one e-mail; returns the supplier's reply (None if the case ended meanwhile)."""
        t = self.threads[supplier_id]
        message, removed = clean_message(self, supplier_id, message)
        if removed:
            self.recorder.metrics.incr("guards.removed", len(removed))
            self.recorder.event("guard_cleaned", session_id=self.session_id, supplier_id=supplier_id, removed=removed)
            log.warning("%s: guard removed %s", supplier_id, removed)
        waited = t.seconds_since_reply()
        if waited > MOVE_LIMIT_S * 0.8:
            log.warning("%s: answering %.0fs after its reply (limit %.0fs)", supplier_id, waited, MOVE_LIMIT_S)
        self.recorder.metrics.observe("decision.seconds_after_reply", waited)
        sheets = [
            {"terms": s["terms"], "c": self.cost(supplier_id, s["terms"])} for s in message.get("term_sheets", [])
        ]
        round_no = t.rounds_used + 1
        self._decision("message", supplier_id, rationale, round=round_no, sheets=sheets)
        self.recorder.event(
            "message_sent",
            session_id=self.session_id,
            case_id=self.case_id,
            supplier_id=supplier_id,
            round=round_no,
            subject=message.get("subject"),
            body=message.get("body"),
            term_sheets=sheets,
            refs=message.get("refs", []),
            seconds_after_reply=round(waited, 2),
        )
        start = time.perf_counter()
        try:
            reply = self.client.send_message(self.session_id, supplier_id, message)
        except ArenaError as e:
            if e.status == 422:
                self.recorder.metrics.incr("moves.invalid")
                self.recorder.event(
                    "invalid_move", session_id=self.session_id, supplier_id=supplier_id, detail=e.detail
                )
                log.error("%s: invalid message: %s", supplier_id, e.detail)
                raise
            if e.status != 409:
                raise
            self.recorder.metrics.incr("moves.conflict")
            self._refresh_after_conflict(supplier_id, e)
            return None if self.ended.is_set() else t.latest
        took = time.perf_counter() - start
        self.recorder.metrics.observe("supplier.reply_seconds", took)
        with t.lock:
            t.messages.append({**message, "from": "buyer", "sent_at": utc_now()})
            t.messages.append(self._with_documents(reply, supplier_id))
            t.last_reply_at = time.monotonic()
        self._log_reply(supplier_id, reply, took, round_no)
        if reply.get("status") in ENDED_STATUSES:
            t.closed = reply["status"]
        return reply

    def _log_reply(self, supplier_id: str, reply: dict, took: float, round_no: int) -> None:
        m = self.recorder.metrics
        status = reply.get("status")
        m.incr(f"supplier.status.{status}")
        claims = reply.get("claim_results") or []
        for c in claims:
            m.incr(f"claims.{c.get('result')}")
        sheet_id, terms = self.threads[supplier_id].standing
        c = self.cost(supplier_id, terms)
        self.recorder.event(
            "reply",
            session_id=self.session_id,
            case_id=self.case_id,
            supplier_id=supplier_id,
            round=round_no,
            status=status,
            sender=reply.get("from"),
            offer_id=sheet_id,
            terms=terms,
            c=c,
            claim_results=claims,
            missing_fields=reply.get("missing_fields"),
            signals=reply.get("signals"),
            seconds=round(took, 2),
            body=reply.get("body"),
            attachments=[a.get("name") for a in reply.get("attachments") or []],
        )
        log.info(
            "%s r%d: %s %s C=%s claims=%s (%.0fs)",
            supplier_id,
            round_no,
            status,
            terms.get("unit_price"),
            _eur(c),
            [x.get("result") for x in claims] or "-",
            took,
        )

    def _refresh_after_conflict(self, supplier_id: str, error: ArenaError) -> None:
        """After a 409: late (timeout), round limit, or the thread/case ended - read the arena's state."""
        self.recorder.event("conflict", session_id=self.session_id, supplier_id=supplier_id, detail=error.detail)
        log.warning("%s: %s", supplier_id, error.detail)
        state = self.client.session(self.session_id)
        if state.get("status") == "ended":
            self.result = state.get("result") or {"deal": False, "end_reason": state.get("end_reason")}
            self.ended.set()
            return
        thread = self.client.thread(self.session_id, supplier_id)
        t = self.threads[supplier_id]
        with t.lock:
            t.messages = [
                self._with_documents(m, supplier_id) if m.get("from") != "buyer" else m
                for m in thread.get("messages", [])
            ]
            t.timeouts = len(thread.get("timeouts") or [])
            t.closed = thread.get("closed")
            t.last_reply_at = time.monotonic()
        if t.timeouts:
            self.recorder.metrics.incr("moves.timeouts")

    def accept(self, supplier_id: str, term_sheet_id: str, rationale: dict | None = None) -> dict:
        if problems := accept_problems(self, supplier_id, term_sheet_id):
            self.recorder.metrics.incr("guards.accept_refused")
            self.recorder.event("guard_refused", session_id=self.session_id, supplier_id=supplier_id, problems=problems)
            raise GuardRefused(f"{supplier_id} {term_sheet_id}: {'; '.join(problems)}")
        terms = self.threads[supplier_id].standing[1]
        self._decision(
            "accept",
            supplier_id,
            rationale,
            term_sheet_id=term_sheet_id,
            terms=terms,
            c=self.cost(supplier_id, terms),
        )
        return self._close(supplier_id, {"action": {"type": "accept", "term_sheet_id": term_sheet_id}})

    def walk_away(self, supplier_id: str | None = None, rationale: dict | None = None) -> dict:
        supplier_id = supplier_id or next(iter(self.threads))
        self._decision("walk_away", supplier_id, rationale)
        return self._close(supplier_id, {"action": {"type": "walk_away"}})

    def _close(self, supplier_id: str, message: dict) -> dict:
        with self._lock:
            if self.ended.is_set():
                return self.result or {}
            try:
                reply = self.client.send_message(self.session_id, supplier_id, message)
                self.result = reply.get("result", reply)
            except ArenaError as e:
                if e.status != 409:
                    raise
                state = self.client.session(self.session_id)
                self.result = state.get("result") or {"deal": False, "end_reason": state.get("end_reason")}
            self.ended.set()
            return self.result

    def _decision(self, kind: str, supplier_id: str, rationale: dict | None, **extra) -> None:
        entry = {
            "ts": utc_now(),
            "t": round(time.time() - self.started, 2),
            "action": kind,
            "supplier_id": supplier_id,
            "rationale": rationale or {},
            **extra,
        }
        self.decisions.append(entry)
        self.recorder.event("decision", session_id=self.session_id, case_id=self.case_id, **entry)

    # ------------------------------------------------------------------ the end
    def finalize(self) -> dict:
        """Read the arena's final state (result, trace, replay), the back office, write the transcript."""
        duration = time.time() - self.started
        state, backoffice = {}, None
        try:
            state = self.client.session(self.session_id)
        except ArenaError as e:
            log.warning("final state: %s", e)
        try:
            backoffice = self.client.backoffice(self.session_id)
        except ArenaError as e:
            backoffice = {"unavailable": str(e.detail)}
        result = state.get("result") or self.result or {}
        outcome = self.outcome(result, state, duration)
        m = self.recorder.metrics
        m.observe("case.seconds", duration)
        m.incr("cases.deal" if result.get("deal") else "cases.no_deal")
        self.recorder.event("result", **outcome)
        self.recorder.save_json(
            f"sessions/{safe_name(self.session_id)}.json",
            {
                "outcome": outcome,
                "case": self.case,
                "threads": {
                    sid: {
                        "messages": t.messages,
                        "closed": t.closed,
                        "timeouts": t.timeouts,
                        "standard_terms": t.standard_terms,
                    }
                    for sid, t in self.threads.items()
                },
                "decisions": self.decisions,
                "result": result,
                "trace": state.get("trace") or result.get("trace"),
                "backoffice": backoffice,
                "state": {k: v for k, v in state.items() if k not in ("result", "trace", "threads")},
            },
        )
        log.info(
            "%s ended (%s): deal=%s score=%s C_deal=%s C_open=%s C_best=%s  %s",
            self.case_id,
            outcome["end_reason"],
            outcome["deal"],
            outcome["score"],
            _eur(outcome["c_deal"]),
            _eur(outcome["c_open"]),
            _eur(outcome["c_best"]),
            outcome["replay_url"] or "",
        )
        return outcome

    def _replay_url(self, state: dict) -> str | None:
        url = state.get("replay_url") or (self.client.replay_url(self.session_id) if self.session_id else None)
        return _absolute(self.client.settings.arena_url, url)

    def outcome(self, result: dict, state: dict, duration: float) -> dict:
        threads = {}
        for sid, t in self.threads.items():
            threads[sid] = {
                "rounds": t.rounds_used,
                "status": t.status,
                "timeouts": t.timeouts,
                "their_prices": t.price_path(),
                "our_prices": t.our_price_path(),
            }
        claims: dict[str, int] = {}
        for t in self.threads.values():
            for msg in t.supplier_messages:
                for c in msg.get("claim_results") or []:
                    claims[c.get("result")] = claims.get(c.get("result"), 0) + 1
        return {
            "run_id": self.recorder.run_id,
            "session_id": self.session_id,
            "case_id": self.case_id,
            "set": self.case.get("set"),
            "title": self.case.get("title"),
            "type": self.case.get("type"),
            "goal": self.buyer.get("category_goal"),
            "strategy": self.strategy_name,
            "suppliers": list(self.threads),
            "deal": bool(result.get("deal")),
            "supplier_id": result.get("supplier_id"),
            "terms": result.get("terms"),
            "must_haves_ok": result.get("must_haves_ok"),
            "end_reason": result.get("end_reason") or state.get("end_reason"),
            "score": result.get("score"),
            "c_open": result.get("c_open"),
            "c_deal": result.get("c_deal"),
            "c_alt": result.get("c_alt"),
            "c_best": result.get("c_best"),
            "saved_eur": (result["c_open"] - (result.get("c_deal") or result.get("c_alt") or 0))
            if result.get("c_open") is not None and (result.get("c_deal") or result.get("c_alt"))
            else None,
            "cost_breakdown": result.get("cost_breakdown"),
            "rounds": sum(t.rounds_used for t in self.threads.values()),
            "threads": threads,
            "claims": claims,
            "seconds": round(duration, 1),
            "replay_url": self._replay_url(state),
        }


def _absolute(base: str, url: str | None) -> str | None:
    if not url:
        return None
    return url if url.startswith("http") else base.rstrip("/") + "/" + url.lstrip("/")


def _running_session(error: ArenaError) -> str | None:
    """A final case played twice answers 409 naming the running session."""
    if error.status != 409:
        return None
    import re

    match = re.search(r"one session per case in the final: (\S+)", str(error.detail))
    return match.group(1).rstrip(".,;") if match else None


def _eur(value) -> str:
    if value is None:
        return "-"
    if isinstance(value, float) and math.isinf(value):
        return "inf"
    return f"{value:,.2f}"

